import{c as r,o as s,b as l}from"./index-nYmZPVNr.js";const n={class:"markdown-body"},a={__name:"Группы: Каскадная рассылка сообщений",setup(g,{expose:t}){return t({frontmatter:{}}),(i,o)=>(s(),r("div",n,[...o[0]||(o[0]=[l('<h2>1. Что такое «Группы» и зачем они нужны</h2><p>Раздел <strong>«Группы»</strong> находится на той же странице, что и <strong>«Аккаунты»</strong> — переключиться между ними можно вкладками в верхней части экрана.</p><p><strong>Группа</strong> — это не папка для сортировки аккаунтов, а настройка <strong>каскадной отправки сообщений</strong>. В группу объединяется несколько уже подключённых каналов (WhatsApp, Telegram, Max, SMS, Email), и для каждого из них задаётся порядок и время ожидания. Логика работы:</p><ol><li>Сообщение сначала уходит через <strong>первый канал</strong> в цепочке.</li><li>Если оно не доставлено или не прочитано в течение заданного времени ожидания — система автоматически пробует <strong>следующий канал</strong>.</li><li>И так далее, пока сообщение не будет доставлено или каскад не закончится.</li></ol><p>Это удобно, когда нужно гарантированно достучаться до клиента: например, сначала попробовать WhatsApp, а если человек им не пользуется — через 2 минуты переключиться на Telegram, а затем на SMS как самый дорогой, но надёжный резервный канал.</p><blockquote><p><strong>Важно:</strong> группа объединяет <strong>целые аккаунты-каналы</strong>, а не отдельные чаты или переписки. Добавить в группу «этот один диалог» нельзя — только весь подключённый аккаунт мессенджера целиком.</p></blockquote><h3>Вкладка «Группы» недоступна, если нет аккаунтов</h3><p>Прежде чем создавать группу, нужно подключить хотя бы один аккаунт <strong>WhatsApp</strong>, <strong>Telegram</strong> или <strong>Max</strong> в разделе «Аккаунты» (см. <a href="%D0%9F%D0%BE%D0%B4%D0%BA%D0%BB%D1%8E%D1%87%D0%B5%D0%BD%D0%B8%D0%B5%20%D0%BC%D0%B5%D1%81%D1%81%D0%B5%D0%BD%D0%B4%D0%B6%D0%B5%D1%80%D0%BE%D0%B2%20%D0%B2%20%D0%9B%D0%B8%D1%87%D0%BD%D0%BE%D0%BC%20%D0%9A%D0%B0%D0%B1%D0%B8%D0%BD%D0%B5%D1%82%D0%B5.md">Подключение мессенджеров в Личном Кабинете</a>). Пока таких аккаунтов нет, вкладка «Группы» задизейблена, а при клике по ней появляется подсказка с просьбой сначала создать аккаунт.</p><hr><h2>2. Создание группы</h2><ol><li>Перейдите на вкладку <strong>Аккаунты → Группы</strong>.</li><li>Если групп ещё нет, нажмите <strong>«Создать первую группу»</strong> (или кнопку создания группы, если группы уже есть).</li><li>В открывшейся форме укажите: <ul><li><strong>Название группы</strong> — обязательное поле, например «Каскад для новых клиентов».</li><li><strong>Порядок отправки сообщений (каскад)</strong> — добавьте нужные каналы кнопками <strong>Telegram / WhatsApp / Max / Email</strong> и перетащите их в нужном порядке (первый в списке — приоритетный).</li></ul></li><li>Нажмите <strong>«Создать»</strong>.</li></ol><blockquote><p>Кнопка «Создать» становится активной только после того, как заполнено название и добавлен хотя бы один канал.</p></blockquote><p>При создании автоматически формируется группа типа «каскад» — на данный момент это единственный доступный тип группы в личном кабинете.</p><hr><h2>3. Добавление и удаление аккаунтов в группе</h2><ul><li><strong>Добавить аккаунт в группу:</strong> на карточке группы нажмите кнопку <strong>«+»</strong>. В списке отметьте нужный аккаунт (или несколько) и подтвердите добавление.</li><li><strong>Убрать аккаунт из группы:</strong> рядом с аккаунтом в списке участников группы нажмите крестик и подтвердите удаление.</li></ul><blockquote><p><strong>Ограничение:</strong> в одну группу можно добавить <strong>не более одного аккаунта каждого типа</strong> — то есть 1 WhatsApp + 1 Telegram + 1 Max + 1 SMS + 1 Email максимум. Второй аккаунт того же мессенджера в ту же группу добавить не получится — для этого нужно создать вторую группу.</p></blockquote><p>Когда аккаунт добавляется или удаляется из группы, каскад пересобирается автоматически: новый канал дописывается в конец очереди, а удалённый — вычищается из порядка отправки без потери настроек для остальных каналов.</p><hr><h2>4. Настройка порядка и времени ожидания каскада</h2><p>Чтобы изменить порядок каналов или настроить паузы между попытками:</p><ol><li>На карточке группы нажмите значок <strong>редактирования (карандаш)</strong>.</li><li>Перетащите каналы, чтобы задать нужный порядок отправки.</li><li>Для каждого канала (кроме последнего) можно указать <strong>время ожидания</strong> перед переключением на следующий канал — в минутах и секундах.</li><li>Сохраните изменения.</li></ol><p>Логика проста: система ждёт указанное время после отправки через канал. Если сообщение за это время не прочитано — отправка автоматически пойдёт по следующему каналу в списке.</p><blockquote><p><strong>Совет:</strong> если в каскаде используется SMS, ставьте его <strong>последним</strong> в очереди. SMS — самый дорогой канал, и если поставить его выше WhatsApp или Telegram, все сообщения будут уходить именно через него, а до более дешёвых каналов очередь просто не дойдёт.</p></blockquote><hr><h2>5. Удаление группы</h2><p>На карточке группы нажмите иконку <strong>корзины</strong> и подтвердите удаление. Действие необратимо — восстановить группу после удаления нельзя.</p><blockquote><p>Системная группа по умолчанию (создаётся автоматически) удалению не подлежит — кнопка удаления для неё скрыта.</p></blockquote><hr><h2>6. Права доступа</h2><p>Отдельной ролевой модели для групп нет: управлять группами (создавать, редактировать, добавлять/удалять аккаунты, удалять группу) может <strong>любой пользователь, авторизованный в личном кабинете</strong> — ограничений по ролям или правам внутри команды не предусмотрено.</p><hr><h2>7. Лимиты и подписка</h2><ul><li><strong>Без подписки</strong> в группу бесплатно можно добавить <strong>по одному аккаунту каждого типа</strong> мессенджера (WhatsApp, Telegram, Max, SMS, Email) — в рамках ограничения «1 аккаунт на тип» из раздела 3.</li><li>Каналы <strong>SMS и Email не лимитируются подпиской вообще</strong> — их можно использовать в группе всегда, независимо от тарифа.</li><li>Если внутри группы нужно больше гибкости по лимитируемым каналам (WhatsApp/Telegram/Max), на карточке группы доступна кнопка <strong>«Подписка»</strong> — там можно оформить платный тариф группы (по числу оплаченных каналов).</li><li>Если тариф понижается или заканчивается и число оплаченных каналов становится меньше текущего состава каскада — лишние каналы автоматически убираются из порядка отправки.</li></ul><hr><h2>8. Пример использования</h2><p><strong>Задача:</strong> гарантированно доставить важное уведомление клиенту, у которого неизвестно, каким мессенджером он пользуется.</p><ol><li>Создаём группу «Важные уведомления».</li><li>Добавляем в каскад: <strong>WhatsApp → Telegram → SMS</strong>.</li><li>Настраиваем ожидание: 2 минуты после WhatsApp, 3 минуты после Telegram.</li><li>Отправляем сообщение через группу вместо отдельного аккаунта.</li></ol><p>Если клиент прочитает сообщение в WhatsApp в течение 2 минут — на этом цепочка закончится. Если нет — через 2 минуты система попробует Telegram, а если и там сообщение не прочитано за 3 минуты — уйдёт SMS как самый надёжный, но самый дорогой резервный канал.</p>',39)])]))}};export{a as default};
